/**
 * @name Path traversal via filesystem access
 * @description Detect use of filesystem APIs that may be vulnerable to path traversal when using untrusted input
 * @kind path-problem
 * @problem.severity warning
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember(["open", "remove", "unlink"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a file path argument, which may lead to path traversal.", source.getNode(), "user input"

/**
 * @name Insecure use of subprocess
 * @description Detect use of subprocess functions that may lead to command injection when passed untrusted input
 * @kind path-problem
 * @problem.severity warning
 * @id py/insecure-subprocess-use
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "check_output", "run"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SubprocessFlow = TaintTracking::Global<SubprocessConfig>;
import SubprocessFlow::PathGraph

from SubprocessFlow::PathNode source, SubprocessFlow::PathNode sink
where SubprocessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a subprocess command argument, which may lead to command injection.", source.getNode(), "user input"
